@dataclass
class GateResult:
    """Outcome of a single verification gate."""
    name: str
    status: str
    method: str
    detail: str = ''
    duration_s: float = 0.0
    evidence: Dict[str, Any] = field(default_factory=dict)

    @property
    def passed(self) -> bool:
        return self.status == PASSED

    @property
    def evaluated(self) -> bool:
        return self.status != SKIPPED

@dataclass
class VerificationReport:
    """Aggregate result across all gates."""
    gates: List[GateResult]
    score_penalty: float
    authored_files: int
    python_files: int
    source: str = 'bundle'
    harness_version: str = '3.0-execution'

    def gate(self, name: str) -> Optional[GateResult]:
        for g in self.gates:
            if g.name == name:
                return g
        return None

    @property
    def evaluated_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.evaluated]

    @property
    def passed_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.passed]

    @property
    def gate_status(self) -> Dict[str, str]:
        """Gate name -> PASSED | FAILED | SKIPPED. The fitness function's input."""
        return {g.name: g.status for g in self.gates}

    @property
    def gate_detail(self) -> Dict[str, str]:
        return {g.name: g.detail for g in self.gates}

    @property
    def pass_rate(self) -> float:
        """Fraction of *evaluated* gates that passed. Skips are excluded."""
        evaluated = self.evaluated_gates
        if not evaluated:
            return 0.0
        passed = len(self.passed_gates)
        return passed / len(evaluated)

    def summary(self) -> str:
        lines = [f"Verification Report ({self.source})"]
        lines.append(f"Authored Files: {self.authored_files} (Python: {self.python_files})")
        lines.append(f"Score Penalty: {self.score_penalty:.2f}")
        lines.append("Gates:")
        for g in self.gates:
            lines.append(f"  [{g.status.upper():7}] {g.name:10} ({g.method}): {g.detail}")
        return "\n".join(lines)

    def to_dict(self) -> Dict[str, Any]:
        return {
            "gates": [
                {
                    "name": g.name,
                    "status": g.status,
                    "method": g.method,
                    "detail": g.detail,
                    "duration_s": g.duration_s,
                    "evidence": g.evidence
                }
                for g in self.gates
            ],
            "score_penalty": self.score_penalty,
            "authored_files": self.authored_files,
            "python_files": self.python_files,
            "source": self.source,
            "harness_version": self.harness_version,
            "pass_rate": self.pass_rate,
            "gate_status": self.gate_status
        }

def extract_code_blocks(text: str) -> Dict[str, str]:
    """Recovers a path->content map from fenced code blocks in a deliverable.

    A last resort, used only when a firm produced no live workspace. Only the
    contents of fenced blocks are returned; the surrounding prose is discarded
    and never reaches a gate.
    """
    if not text:
        return {}

    # Regex to find fenced code blocks with optional language and optional filename hint
    # Pattern: ```[lang] [filename]\n...\n```
    # We look for blocks that might contain a filename in the info string or just assume sequential naming if not found.
    # However, the spec says "path->content map". Usually, agents write ```python path/to/file.py
    # Let's try to extract filename from the info string.

    pattern = r'```(?:\w+)?\s+([^\n`]+)?\n(.*?)```'
    matches = re.findall(pattern, text, re.DOTALL)

    bundle = {}
    counter = 0
    for match in matches:
        info_str = match[0]
        content = match[1]

        # Try to extract a filename from the info string
        # Common patterns: "python src/main.py", "src/main.py", "main.py"
        filename = None
        if info_str:
            parts = info_str.split()
            for part in parts:
                if '.' in part and not part.startswith('-'):
                    # Heuristic: looks like a filename
                    filename = part
                    break

        if not filename:
            # Fallback filename
            filename = f"extracted_block_{counter}.py"
            counter += 1

        # Clean up filename (remove potential markdown artifacts if any leaked)
        filename = filename.strip()

        bundle[filename] = content

    return bundle

class ExecutionHarness:
    """Materializes a workspace bundle and verifies it by actually running it."""

    def __init__(self, timeout_s: int=DEFAULT_TIMEOUT_S, penalty_per_gate: float=DEFAULT_PENALTY_PER_GATE, python_executable: Optional[str]=None):
        self.timeout_s = timeout_s
        self.penalty_per_gate = penalty_per_gate
        self.python_executable = python_executable or sys.executable

    def verify_workspace(self, workspace: Any=None, deliverable_text: str='') -> VerificationReport:
        """Verifies whatever code a firm actually produced.

        This is the entry point tournaments use. A firm normally writes into a
        live `AgentWorkspace`; if it never did, we fall back to the fenced code
        blocks embedded in its written deliverable.

        `deliverable_text` is *only* mined for code blocks. Its prose is never
        passed to a gate, because the entire point of this harness is that an
        essay about OpenTelemetry cannot satisfy the telemetry gate.
        """
        bundle = None
        source = 'bundle'

        # Try to get bundle from workspace object if it has a method or attribute
        if workspace is not None:
            if hasattr(workspace, 'get_bundle'):
                bundle = workspace.get_bundle()
            elif hasattr(workspace, 'files'):
                bundle = workspace.files
            elif isinstance(workspace, dict):
                bundle = workspace

        if not bundle:
            bundle = extract_code_blocks(deliverable_text)
            source = 'deliverable'

        if not bundle:
            # Empty workspace
            return self._create_empty_report(source)

        return self.verify_bundle(bundle, source=source)

    def verify_bundle(self, bundle: Dict[str, str], source: str='bundle') -> VerificationReport:
        """Verifies an in-memory path->content map by writing it to a temp dir."""
        # Filter bundle using artifacts logic
        filtered_bundle = filter_bundle(bundle)

        if not filtered_bundle:
            return self._create_empty_report(source)

        with tempfile.TemporaryDirectory() as tmpdir:
            # Write files to temp dir
            for path, content in filtered_bundle.items():
                full_path = os.path.join(tmpdir, path)
                os.makedirs(os.path.dirname(full_path), exist_ok=True)
                with open(full_path, 'w', encoding='utf-8') as f:
                    f.write(content)

            return self.verify_directory(tmpdir, authored=filtered_bundle, source=source)

    def verify_directory(self, workdir: str, authored: Optional[Dict[str, str]]=None, source: str='directory') -> VerificationReport:
        """Verifies an existing workspace directory."""
        start_time = time.time()

        # Collect files
        all_files = []
        for root, dirs, files in os.walk(workdir):
            # Prune excluded dirs
            dirs[:] = [d for d in dirs if not is_generated_path(os.path.join(root, d))]
            for file in files:
                rel_path = os.path.relpath(os.path.join(root, file), workdir)
                if not is_generated_path(rel_path) and not is_malformed_path(rel_path):
                    all_files.append(rel_path)

        python_files = [f for f in all_files if f.endswith('.py')]
        authored_count = len(all_files)
        python_count = len(python_files)

        gates = []

        # Gate 1: Syntax
        gates.append(self._gate_syntax(workdir, python_files))

        # Gate 2: Build
        gates.append(self._gate_build(workdir))

        # Gate 3: Smoke
        gates.append(self._gate_smoke(workdir, python_files))

        # Gate 4: Tests
        gates.append(self._gate_tests(workdir, python_files))

        # Gate 5: Telemetry
        gates.append(self._gate_telemetry(workdir, python_files))

        # Calculate penalty
        failed_count = sum(1 for g in gates if g.status == FAILED)
        score_penalty = failed_count * self.penalty_per_gate

        return VerificationReport(
            gates=gates,
            score_penalty=score_penalty,
            authored_files=authored_count,
            python_files=python_count,
            source=source,
            harness_version='3.0-execution'
        )

    def _create_empty_report(self, source: str) -> VerificationReport:
        gates = [
            GateResult(name='syntax', status=FAILED, method='ast.parse', detail='No python files found'),
            GateResult(name='build', status=FAILED, method='metadata_check', detail='No build metadata found'),
            GateResult(name='smoke', status=FAILED, method='import_check', detail='No modules to import'),
            GateResult(name='tests', status=FAILED, method='pytest_run', detail='No tests found'),
            GateResult(name='telemetry', status=FAILED, method='ast_analysis', detail='No python files to analyze'),
        ]
        return VerificationReport(
            gates=gates,
            score_penalty=5 * self.penalty_per_gate,
            authored_files=0,
            python_files=0,
            source=source,
            harness_version='3.0-execution'
        )

    def _gate_syntax(self, workdir: str, python_files: List[str]) -> GateResult:
        start = time.time()
        if not python_files:
            return GateResult(name='syntax', status=FAILED, method='ast.parse', detail='No python files', duration_s=time.time()-start)

        errors = []
        for f in python_files:
            path = os.path.join(workdir, f)
            try:
                with open(path, 'r', encoding='utf-8') as fp:
                    ast.parse(fp.read())
            except SyntaxError as e:
                errors.append(f"{f}: {e}")
            except Exception as e:
                errors.append(f"{f}: {e}")

        if errors:
            return GateResult(name='syntax', status=FAILED, method='ast.parse', detail='; '.join(errors), duration_s=time.time()-start)

        return GateResult(name='syntax', status=PASSED, method='ast.parse', detail='All files parsed', duration_s=time.time()-start)

    def _gate_build(self, workdir: str) -> GateResult:
        start = time.time()
        pyproject = os.path.join(workdir, 'pyproject.toml')
        setup_py = os.path.join(workdir, 'setup.py')
        setup_cfg = os.path.join(workdir, 'setup.cfg')

        has_metadata = False
        detail = ''

        if os.path.exists(pyproject):
            has_metadata = True
            try:
                with open(pyproject, 'rb') as f:
                    data = tomllib.load(f)
                if not any(k in data for k in ['project', 'build-system', 'tool']):
                    return GateResult(name='build', status=FAILED, method='tomllib', detail='pyproject.toml missing required tables', duration_s=time.time()-start)
            except Exception as e:
                return GateResult(name='build', status=FAILED, method='tomllib', detail=f'pyproject.toml invalid: {e}', duration_s=time.time()-start)
        elif os.path.exists(setup_py) or os.path.exists(setup_cfg):
            has_metadata = True
        else:
            return GateResult(name='build', status=FAILED, method='metadata_check', detail='No build metadata found', duration_s=time.time()-start)

        # Try pip install
        try:
            # Check if pip is available
            subprocess.run([self.python_executable, '-m', 'pip', '--version'], check=True, capture_output=True, timeout=10)

            # Run pip install
            cmd = [self.python_executable, '-m', 'pip', 'install', '-e', '.', '--no-deps', '--no-build-isolation']
            result = subprocess.run(cmd, cwd=workdir, capture_output=True, text=True, timeout=self.timeout_s)

            if result.returncode != 0:
                return GateResult(name='build', status=FAILED, method='pip_install', detail=f'pip install failed: {result.stderr}', duration_s=time.time()-start)

            return GateResult(name='build', status=PASSED, method='pip_install', detail='Installed successfully', duration_s=time.time()-start)

        except FileNotFoundError:
            return GateResult(name='build', status=SKIPPED, method='pip_install', detail='pip not available', duration_s=time.time()-start)
        except subprocess.TimeoutExpired:
            return GateResult(name='build', status=FAILED, method='pip_install', detail='pip install timed out', duration_s=time.time()-start)
        except Exception as e:
            return GateResult(name='build', status=FAILED, method='pip_install', detail=f'Error during install: {e}', duration_s=time.time()-start)

    def _gate_smoke(self, workdir: str, python_files: List[str]) -> GateResult:
        start = time.time()
        # Identify non-test modules
        # Exclude test files
        non_test_modules = []
        for f in python_files:
            if 'test' in os.path.basename(f).lower():
                continue
            # Convert path to module name
            # e.g. src/foo/bar.py -> foo.bar (if src is on path)
            # We will add workdir and workdir/src to PYTHONPATH
            rel_path = f
            if rel_path.startswith('src/'):
                rel_path = rel_path[4:]
            if rel_path.endswith('.py'):
                module_name = rel_path[:-3].replace('/', '.').replace('\\', '.')
                if module_name:
                    non_test_modules.append(module_name)

        if not non_test_modules:
            return GateResult(name='smoke', status=FAILED, method='import_check', detail='No importable modules', duration_s=time.time()-start)

        # Construct PYTHONPATH
        env = os.environ.copy()
        current_path = env.get('PYTHONPATH', '')
        new_paths = [workdir, os.path.join(workdir, 'src')]
        if current_path:
            new_paths.append(current_path)
        env['PYTHONPATH'] = os.pathsep.join(new_paths)

        # Try importing each module
        import_errors = []
        module_not_found_errors = []

        for module in non_test_modules:
            code = f"import {module}"
            try:
                result = subprocess.run(
                    [self.python_executable, '-c', code],
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=10
                )
                if result.returncode != 0:
                    stderr = result.stderr
                    if 'ModuleNotFoundError' in stderr:
                        # Check if it's a third-party package (not the module itself)
                        # If the module itself is not found, it's a failure.
                        # But if it's a dependency, it's skipped.
                        # Heuristic: if the error says "No module named 'module_name'", it's a failure.
                        # If it says "No module named 'some_dep'", it's skipped.
                        if f"No module named '{module}'" in stderr or f"No module named \"{module}\"" in stderr:
                            import_errors.append(f"{module}: Module not found")
                        else:
                            module_not_found_errors.append(f"{module}: Dependency missing")
                    else:
                        import_errors.append(f"{module}: {stderr.strip()}")
            except Exception as e:
                import_errors.append(f"{module}: {e}")

        if import_errors:
            return GateResult(name='smoke', status=FAILED, method='import_check', detail='; '.join(import_errors), duration_s=time.time()-start)

        if module_not_found_errors:
            return GateResult(name='smoke', status=SKIPPED, method='import_check', detail='Third-party dependencies missing', duration_s=time.time()-start)

        return GateResult(name='smoke', status=PASSED, method='import_check', detail='All modules imported', duration_s=time.time()-start)

    def _gate_tests(self, workdir: str, python_files: List[str]) -> GateResult:
        start = time.time()
        # Find test files
        test_files = [f for f in python_files if 'test' in os.path.basename(f).lower()]

        if not test_files:
            return GateResult(name='tests', status=FAILED, method='discover', detail='No test files found', duration_s=time.time()-start)

        env = os.environ.copy()
        current_path = env.get('PYTHONPATH', '')
        new_paths = [workdir, os.path.join(workdir, 'src')]
        if current_path:
            new_paths.append(current_path)
        env['PYTHONPATH'] = os.pathsep.join(new_paths)

        # Try pytest
        try:
            subprocess.run([self.python_executable, '-m', 'pytest', '--version'], check=True, capture_output=True, timeout=10)
            cmd = [self.python_executable, '-m', 'pytest', '-v'] + test_files
            result = subprocess.run(cmd, cwd=workdir, env=env, capture_output=True, text=True, timeout=self.timeout_s)

            if result.returncode == 0:
                return GateResult(name='tests', status=PASSED, method='pytest', detail='All tests passed', duration_s=time.time()-start)
            else:
                # Check if failure is due to ModuleNotFoundError during collection
                if 'ModuleNotFoundError' in result.stderr or 'ModuleNotFoundError' in result.stdout:
                    if 'error collecting' in result.stderr.lower() or 'import error' in result.stderr.lower():
                         return GateResult(name='tests', status=SKIPPED, method='pytest', detail='Import error during collection', duration_s=time.time()-start)
                return GateResult(name='tests', status=FAILED, method='pytest', detail='Tests failed', duration_s=time.time()-start)

        except FileNotFoundError:
            pass # Fallback to stdlib
        except Exception:
            pass # Fallback to stdlib

        # Stdlib fallback
        # Run a script that imports each test file and runs tests
        test_script = []
        test_script.append('import sys')
        test_script.append('import unittest')
        test_script.append('import importlib')
        test_script.append('import inspect')
        test_script.append('import traceback')
        test_script.append('import os')

        # Add paths
        test_script.append(f'sys.path.insert(0, r{workdir!r})')
        test_script.append(f'sys.path.insert(0, r{os.path.join(workdir, "src")!r})')

        test_script.append('failed = False')
        test_script.append('skipped = False')
        test_script.append('collected = 0')

        for tf in test_files:
            module_name = tf.replace('/', '.').replace('\\', '.')
            if module_name.endswith('.py'):
                module_name = module_name[:-3]

            test_script.append('try:')
            test_script.append(f'    mod = importlib.import_module({module_name!r})')

            # Collect unittest.TestCase subclasses
            test_script.append('    suite = unittest.TestLoader().loadTestsFromModule(mod)')
            test_script.append('    if suite.countTestCases() > 0:')
            test_script.append('        collected += suite.countTestCases()')
            test_script.append('        runner = unittest.TextTestRunner(verbosity=0)')
            test_script.append('        res = runner.run(suite)')
            test_script.append('        if not res.wasSuccessful():')
            test_script.append('            failed = True')

            # Collect bare def test_*() functions
            test_script.append('    for name, obj in inspect.getmembers(mod):')
            test_script.append('        if name.startswith("test_") and inspect.isfunction(obj):')
            test_script.append('            try:')
            test_script.append('                sig = inspect.signature(obj)')
            test_script.append('                if len(sig.parameters) == 0:')
            test_script.append('                    collected += 1')
            test_script.append('                    obj()')
            test_script.append('            except Exception:')
            test_script.append('                failed = True')

            test_script.append('except ModuleNotFoundError as e:')
            test_script.append(f'    if {module_name!r} in str(e):')
            test_script.append('        failed = True')
            test_script.append('    else:')
            test_script.append('        skipped = True')
            test_script.append('except Exception as e:')
            test_script.append('    failed = True')

        test_script.append('if failed:')
        test_script.append('    sys.exit(1)')
        test_script.append('elif skipped and collected == 0:')
        test_script.append('    sys.exit(2)') # Special code for skipped
        test_script.append('else:')
        test_script.append('    sys.exit(0)')

        script_content = '\n'.join(test_script)

        try:
            result = subprocess.run(
                [self.python_executable, '-c', script_content],
                env=env,
                capture_output=True,
                text=True,
                timeout=self.timeout_s
            )

            if result.returncode == 0:
                return GateResult(name='tests', status=PASSED, method='unittest', detail='All tests passed', duration_s=time.time()-start)
            elif result.returncode == 2:
                return GateResult(name='tests', status=SKIPPED, method='unittest', detail='Tests skipped due to missing deps', duration_s=time.time()-start)
            else:
                return GateResult(name='tests', status=FAILED, method='unittest', detail='Tests failed', duration_s=time.time()-start)

        except Exception as e:
            return GateResult(name='tests', status=FAILED, method='unittest', detail=f'Error running tests: {e}', duration_s=time.time()-start)

    def _gate_telemetry(self, workdir: str, python_files: List[str]) -> GateResult:
        start = time.time()
        if not python_files:
            return GateResult(name='telemetry', status=FAILED, method='ast_analysis', detail='No python files', duration_s=time.time()-start)

        has_import = False
        has_call = False

        tracer_methods = {
            'start_as_current_span', 'start_span', 'get_tracer', 
            'get_tracer_provider', 'set_tracer_provider', 'get_meter'
        }

        for f in python_files:
            path = os.path.join(workdir, f)
            try:
                with open(path, 'r', encoding='utf-8') as fp:
                    tree = ast.parse(fp.read())

                for node in ast.walk(tree):
                    # Check for import
                    if isinstance(node, ast.Import):
                        for alias in node.names:
                            if alias.name == 'opentelemetry' or alias.name.startswith('opentelemetry.'):
                                has_import = True
                    elif isinstance(node, ast.ImportFrom):
                        if node.module == 'opentelemetry' or (node.module and node.module.startswith('opentelemetry.')):
                            has_import = True

                    # Check for call
                    if isinstance(node, ast.Call):
                        func = node.func
                        if isinstance(func, ast.Attribute):
                            if func.attr in tracer_methods:
                                has_call = True
                        elif isinstance(func, ast.Name):
                            if func.id in tracer_methods:
                                has_call = True

            except Exception:
                continue

        if has_import and has_call:
            return GateResult(name='telemetry', status=PASSED, method='ast_analysis', detail='Telemetry detected', duration_s=time.time()-start)
        else:
            detail = []
            if not has_import:
                detail.append('No opentelemetry import')
            if not has_call:
                detail.append('No tracer/span calls')
            return GateResult(name='telemetry', status=FAILED, method='ast_analysis', detail='; '.join(detail), duration_s=time.time()-start)

